//! The BlueV3 text-handling contract: every case of `tests/golden/cases.jsonl`
//! (generated by BlueV3 `tests/golden/make_golden.py` from the Python
//! reference `site_flow.py`; the format is its `tests/golden/README.md`).
//!
//! Each `plan` case is checked stage by stage (prepared, tagged, phonemes,
//! chunks, token_ids) and the first stage that differs is reported; `pack`
//! cases check the chunk packer alone and `geometry` cases the latent width.
//!
//! The file is vendored next to this test with the reference's `vocab.json`.
//! `BLUEV3_GOLDEN=<path to cases.jsonl>` reads another copy. To refresh the
//! vendored one after the reference changes, regenerate it in BlueV3 and copy
//! `tests/golden/cases.jsonl` and `vocab.json` here.
//!
//! The G2Ps are the release's: RenikudPlus (`BLUEV3_RENIKUD=<onnx>`) and
//! polyg2p's data (`BLUEV3_POLYG2P_DATA=<dir>`), both by default from the
//! bundle in `MAMBOTTS_BLUE_MODEL_DIR` or the installed MamboTTS
//! `bluev3-3.0.0` bundle. The golden file was made with RenikudPlus's float
//! `model.onnx` (BlueV3's `renikud.onnx`); the bundle ships the int8 export,
//! which reads a few words differently. With the bundle's model (no
//! `BLUEV3_RENIKUD`), a Hebrew case whose first difference is its phonemes is
//! reported as int8 drift rather than failed; point `BLUEV3_RENIKUD` at the
//! float model for the strict check. A case whose G2P is not found is skipped
//! and counted.

use std::path::{Path, PathBuf};

use blue_rs::{
    TokenEncoder, chunk_phonemes, handling::tag_latin_runs, latent_geometry, plan_text,
    phonemize::{Language, Phonemizer},
};
use serde_json::Value;

const REFERENCE: &str = "/Users/maxm/Documents/Project Blue/BlueV3/tests/golden/cases.jsonl";
const MAX_CHUNK_TOKENS: usize = 300;

fn vendored(name: &str) -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/golden").join(name)
}

/// The installed release bundle, if any.
fn bundle_dir() -> Option<PathBuf> {
    if let Some(dir) = std::env::var_os("MAMBOTTS_BLUE_MODEL_DIR") {
        return Some(PathBuf::from(dir));
    }
    let home = PathBuf::from(std::env::var_os("HOME")?);
    [
        "Library/Application Support/com.maxmelichov.mambotts/models/bluev3-3.0.0",
        ".local/share/com.maxmelichov.mambotts/models/bluev3-3.0.0",
    ]
    .into_iter()
    .map(|rel| home.join(rel))
    .find(|dir| dir.is_dir())
}

fn model_path(var: &str, in_bundle: &str) -> Option<PathBuf> {
    match std::env::var_os(var) {
        Some(path) => Some(PathBuf::from(path)),
        None => bundle_dir().map(|dir| dir.join(in_bundle)),
    }
    .filter(|path| path.exists())
}

fn strings(value: &Value) -> Vec<String> {
    value
        .as_array()
        .map(|items| items.iter().map(|s| s.as_str().unwrap_or_default().to_owned()).collect())
        .unwrap_or_default()
}

fn id_rows(value: &Value) -> Vec<Vec<i64>> {
    value
        .as_array()
        .map(|rows| {
            rows.iter()
                .map(|row| row.as_array().unwrap().iter().map(|id| id.as_i64().unwrap()).collect())
                .collect()
        })
        .unwrap_or_default()
}

/// The first stage whose value differs, as a report line.
fn first_difference(stages: &[(&str, String, String)]) -> Option<String> {
    stages
        .iter()
        .find(|(_, got, want)| got != want)
        .map(|(stage, got, want)| format!("{stage}\n      got:  {got}\n      want: {want}"))
}

#[test]
fn golden_cases() {
    let path = std::env::var_os("BLUEV3_GOLDEN")
        .map(PathBuf::from)
        .unwrap_or_else(|| vendored("cases.jsonl"));
    let Ok(raw) = std::fs::read_to_string(&path) else {
        eprintln!("SKIP golden_cases: no golden file at {}", path.display());
        return;
    };
    if std::env::var_os("BLUEV3_GOLDEN").is_none()
        && std::fs::read_to_string(REFERENCE).is_ok_and(|reference| reference != raw)
    {
        eprintln!("WARNING: the vendored cases.jsonl differs from {REFERENCE}: refresh it");
    }
    let encoder = TokenEncoder::from_json(vendored("vocab.json")).expect("vocab.json");

    let renikud = model_path("BLUEV3_RENIKUD", "renikud-plus.onnx");
    let poly_data = model_path("BLUEV3_POLYG2P_DATA", "polyg2p");
    eprintln!("renikud: {renikud:?}\npolyg2p: {poly_data:?}");
    let mut phonemizer =
        Phonemizer::open(renikud.as_deref(), poly_data.as_deref(), Language::Hebrew)
            .expect("phonemizer");
    // The bundle's int8 RenikudPlus is not the golden file's float model.
    let int8_renikud = std::env::var_os("BLUEV3_RENIKUD").is_none();
    let have = |g2p: &str| match g2p {
        "renikud" => renikud.is_some(),
        "polyg2p" => poly_data.is_some(),
        _ => false,
    };

    let (mut pass, mut skip, mut drift) = (0, Vec::new(), Vec::new());
    let mut failures = Vec::new();
    for line in raw.lines().filter(|line| !line.trim().is_empty()) {
        let case: Value = serde_json::from_str(line).expect("a JSON case");
        let id = case["id"].as_str().unwrap_or("?").to_owned();
        let expect = &case["expect"];
        let lang = case["lang"].as_str().unwrap_or("");
        let ids = |chunks: &[String]| -> Vec<Vec<i64>> {
            chunks.iter().map(|c| encoder.token_ids(c, lang).unwrap()).collect()
        };
        let diff = match case["kind"].as_str() {
            Some("geometry") => {
                let got = latent_geometry(
                    case["duration_s"].as_f64().unwrap() as f32,
                    case["sample_rate"].as_u64().unwrap() as usize,
                    case["frame_len"].as_u64().unwrap() as usize,
                );
                let want = (
                    expect["t_lat"].as_u64().unwrap() as usize,
                    expect["t_mask"].as_u64().unwrap() as usize,
                );
                first_difference(&[("geometry", format!("{got:?}"), format!("{want:?}"))])
            }
            Some("pack") => {
                let units = strings(&case["phonemes"]);
                let chunks = chunk_phonemes(units.iter().map(String::as_str), lang, MAX_CHUNK_TOKENS);
                first_difference(&[
                    ("chunks", format!("{chunks:?}"), format!("{:?}", strings(&expect["chunks"]))),
                    ("token_ids", format!("{:?}", ids(&chunks)), format!("{:?}", id_rows(&expect["token_ids"]))),
                ])
            }
            Some("plan") => {
                let missing: Vec<String> = strings(&case["g2p"]).into_iter().filter(|g| !have(g)).collect();
                if !missing.is_empty() {
                    skip.push(format!("{id} (needs {})", missing.join(", ")));
                    continue;
                }
                let text = case["text"].as_str().unwrap();
                match plan_text(&mut phonemizer, text, lang, MAX_CHUNK_TOKENS) {
                    Err(error) if expect.get("error").is_some() => {
                        let _ = error;
                        None
                    }
                    Err(error) => Some(format!("plan failed: {error:#}")),
                    Ok(_) if expect.get("error").is_some() => Some("plan should have failed".into()),
                    Ok(plan) => first_difference(&[
                        ("prepared", plan.prepared.clone(), expect["prepared"].as_str().unwrap().to_owned()),
                        ("tagged", tag_latin_runs(&plan.prepared, lang), expect["tagged"].as_str().unwrap().to_owned()),
                        ("phonemes", format!("{:?}", plan.phonemes), format!("{:?}", strings(&expect["phonemes"]))),
                        ("chunks", format!("{:?}", plan.chunks), format!("{:?}", strings(&expect["chunks"]))),
                        ("token_ids", format!("{:?}", ids(&plan.chunks)), format!("{:?}", id_rows(&expect["token_ids"]))),
                    ]),
                }
            }
            other => Some(format!("unknown kind {other:?}")),
        };
        let renikud_case = strings(&case["g2p"]).iter().any(|g| g == "renikud");
        match diff {
            None => pass += 1,
            Some(diff) if int8_renikud && renikud_case && diff.starts_with("phonemes") => {
                drift.push(format!("{id}: {diff}"));
            }
            Some(diff) => failures.push(format!("{id}: {diff}")),
        }
    }

    for line in &skip {
        eprintln!("SKIP {line}");
    }
    for line in &drift {
        eprintln!("INT8 {line}");
    }
    for line in &failures {
        eprintln!("FAIL {line}");
    }
    eprintln!(
        "golden: {pass} passed, {} skipped, {} int8 G2P drift, {} failed ({})",
        skip.len(),
        drift.len(),
        failures.len(),
        path.display()
    );
    assert!(failures.is_empty(), "{} golden cases failed", failures.len());
}
